begin;
set local search_path=public,extensions;
select plan(24);
select has_table('public','studio_foundation_lessons','Versioned foundations content exists');
select has_table('public','studio_foundation_positions','Private position revisions exist');
select has_table('public','studio_foundation_events','Separate practice evidence exists');
select ok(not has_table_privilege('authenticated','learning_private.foundation_answer_keys','SELECT'),'Keys stay private');
select ok(not has_table_privilege('authenticated','public.studio_foundation_positions','INSERT'),'Direct position insert denied');
select ok(not has_table_privilege('authenticated','public.studio_foundation_events','UPDATE'),'Direct grade updates denied');
insert into auth.users(id,email) values('a4622000-0000-0000-0000-000000000001','foundation-policy-a@example.test'),('a4622000-0000-0000-0000-000000000002','foundation-policy-b@example.test');
update public.profiles set goal='Understand campus event requests' where user_id in ('a4622000-0000-0000-0000-000000000001','a4622000-0000-0000-0000-000000000002');
set local role anon;
select throws_ok($$select public.get_studio_foundation('system-design-studio-v1','web-request-v1')$$,'42501','permission denied for function get_studio_foundation','Anonymous lesson read denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a4622000-0000-0000-0000-000000000001',true);
select is(public.get_studio_foundation('system-design-studio-v1','web-request-v1')->>'enrolled','false','Existing enrolment required');
select lives_ok($$select public.enrol_course('system-design-studio-v1')$$,'Reuses Studio enrolment without JS prerequisite');
select throws_ok($$select public.get_studio_foundation('javascript-foundations-v1','web-request-v1')$$,'22023','Unknown foundation lesson','Unrelated course rejected');
select is(public.save_studio_foundation('web-request-v1','web-request-content-v1','foundation-position-v1',0,'a4622000-0000-0000-0000-000000000003','{"section":"learn","step":1,"viewed":false}'::jsonb)->>'revision','1','Explicit position save');
select is(public.save_studio_foundation('web-request-v1','web-request-content-v1','foundation-position-v1',0,'a4622000-0000-0000-0000-000000000003','{"section":"learn","step":1,"viewed":false}'::jsonb)->>'revision','1','Retry saves once');
select throws_ok($$select public.save_studio_foundation('web-request-v1','web-request-content-v1','foundation-position-v1',0,gen_random_uuid(),'{"section":"learn","step":0,"viewed":false}'::jsonb)$$,'40001','A newer lesson position exists','Stale position cannot overwrite');
select throws_ok($$select public.submit_studio_foundation('web-request-v1','web-request-content-v1','foundation-position-v1','initiator','hint',null,gen_random_uuid())$$,'22023','Try the question before requesting help','No hint before attempt');
select is(public.submit_studio_foundation('web-request-v1','web-request-content-v1','foundation-position-v1','initiator','attempt','database','a4622000-0000-0000-0000-000000000004')->>'correct','false','Server evaluates first attempt');
select is(public.submit_studio_foundation('web-request-v1','web-request-content-v1','foundation-position-v1','initiator','hint',null,'a4622000-0000-0000-0000-000000000005')->>'hintLevel','1','Hint evidence recorded');
select is(public.submit_studio_foundation('web-request-v1','web-request-content-v1','foundation-position-v1','initiator','attempt','browser','a4622000-0000-0000-0000-000000000006')->>'independent','false','Correct retry is not independent first attempt');
select is(jsonb_array_length(public.export_learner_data()->'studio_foundation_positions'),1,'Owned position exported');
select is(jsonb_array_length(public.export_learner_data()->'studio_foundation_events'),3,'Attempt and help evidence exported');
select is((select count(*) from public.attempts),0::bigint,'No fabricated JS grades');
select set_config('request.jwt.claim.sub','a4622000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.studio_foundation_positions),0::bigint,'Other learner cannot read position');
select is((select count(*) from public.studio_foundation_events),0::bigint,'Other learner cannot read evidence');
reset role;
delete from auth.users where id='a4622000-0000-0000-0000-000000000001';
select is((select count(*) from public.studio_foundation_positions where user_id='a4622000-0000-0000-0000-000000000001'),0::bigint,'Synthetic Auth deletion cascades positions');
select is((select count(*) from public.studio_foundation_events where user_id='a4622000-0000-0000-0000-000000000001'),0::bigint,'Synthetic Auth deletion cascades practice');
select * from finish();
rollback;
